 * distributed under the License is distributed on an "AS IS" BASIS, WITHOUT
 * WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.  See the
 * License for the specific language governing permissions and limitations
 * under the License.
 *
 ****************************************************************************/

/* BK7258 PSRAM controller driver.
 *
 * Initializes the on-chip PSRAM controller and detects the external
 * PSRAM chip via the command-register interface.  Provides a minimal
 * NSH command "psram" for bring-up verification.
 *
 * Source: Armino psram_driver.c + psram_hal.c, Beken, Apache-2.0
 *
 * NOTE: This driver does NOT configure MPU or D-cache.  The BK7258
 * port currently runs without CONFIG_ARMV8M_DCACHE; cache
 * coherency is not addressed here.
 */

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include <nuttx/nuttx.h>

#include "arm_internal.h"
#include "hardware/bk7258_psram.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Busy-wait calibration: ~1 iteration per CPU cycle at 320 MHz.
 * Values taken from Armino; not critical (only used for power
 * settling delays).
 */

#define PSRAM_DELAY_SHORT      500
#define PSRAM_DELAY_LONG       3000
#define CMD_READ_RETRIES       5
#define CMD_READ_POLL_OUTER    10
#define CMD_READ_POLL_INNER    5000

/****************************************************************************
 * Private Data
 ****************************************************************************/

static uint32_t g_psram_chip_id;
static uint32_t g_psram_size;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: psram_busy_delay
 *
 * Description:
 *   Simple busy-wait loop.  Duration is approximate and non-critical;
 *   used only for power/settling delays during initialization.
 *
 ****************************************************************************/

static void psram_busy_delay(uint32_t count)
{
  volatile uint32_t i;

  for (i = 0; i < count; i++)
    {
    }
}

/****************************************************************************
 * Name: psram_putreg / psram_getreg
 *
 * Description:
 *   Raw 32-bit register access helpers.
 *
 ****************************************************************************/

static inline void psram_putreg(uint32_t val, uint32_t addr)
{
  *(volatile uint32_t *)addr = val;
}

static inline uint32_t psram_getreg(uint32_t addr)
{
  return *(volatile uint32_t *)addr;
}

/****************************************************************************
 * Name: psram_set_voltage
 *
 * Description:
 *   Configure PSRAM LDO voltage to 1.95V (psldo_swb=1, vpsramsel=3)
 *   and enable the LDO.  Wait 1 ms for stabilization.
 *
 * Source: Armino sys_psram_driver.c -> sys_drv_psram_psldo_vsel()
 *         + sys_drv_psram_ldo_enable()
 ****************************************************************************/

static void psram_set_voltage(void)
{
  psram_putreg(PSRAM_VOLTAGE_LDO_EN, SYS_ANA_REG13);
  up_mdelay(1);
}

/****************************************************************************
 * Name: psram_enable_clock
 *
 * Description:
 *   Set PSRAM clock to 80 MHz for init phase (source=320 MHz PLL,
 *   divider=1).  The higher default clock is set after init completes.
 *
 * Source: Armino psram_hal.c -> psram_hal_set_clk(PSRAM_80M)
 ****************************************************************************/

static void psram_enable_clock(void)
{
  uint32_t val;

  /* Select 320 MHz PLL as source, divider = 1 -> 80 MHz */

  val = psram_getreg(SYS_CPU_CLK_DIV2);
  val &= ~(CLK_DIV2_CKSEL_PSRAM | CLK_DIV2_CKDIV_PSRAM);
  val |= CLK_DIV2_CKDIV_PSRAM;
  psram_putreg(val, SYS_CPU_CLK_DIV2);
}

/****************************************************************************
 * Name: psram_set_default_clock
 *
 * Description:
 *   Switch PSRAM clock to 120 MHz (source=480 MHz PLL, divider=1).
 *   Called after init completes.
 *
 * Source: Armino psram_hal.c -> psram_hal_set_default_clk()
 ****************************************************************************/

static void psram_set_default_clock(void)
{
  uint32_t val;

  val = psram_getreg(SYS_CPU_CLK_DIV2);
  val &= ~(CLK_DIV2_CKSEL_PSRAM | CLK_DIV2_CKDIV_PSRAM);
  val |= (CLK_DIV2_CKSEL_PSRAM | CLK_DIV2_CKDIV_PSRAM);
  psram_putreg(val, SYS_CPU_CLK_DIV2);
}

/****************************************************************************
 * Name: psram_release_sf_reset
 *
 * Description:
 *   Release the PSRAM serial-flash interface from reset.
 *
 * Source: Armino psram_hal.c -> psram_hal_set_sf_reset(1)
 ****************************************************************************/

static void psram_release_sf_reset(void)
{
  psram_putreg(PSRAM_SF_RESET_BIT, PSRAM_LL_REG2);
}

/****************************************************************************
 * Name: psram_cmd_reset
 *
 * Description:
 *   Issue a reset command to the PSRAM chip via the command interface.
 *
 * Source: Armino psram_hal.c -> psram_hal_set_cmd_reset()
 ****************************************************************************/

static void psram_cmd_reset(void)
{
  psram_putreg(PSRAM_CMD_RESET, PSRAM_LL_REG8);
}

/****************************************************************************
 * Name: psram_cmd_write
 *
 * Description:
 *   Write a value to a PSRAM register address via the command
 *   interface (REG9=addr, REG_A=value, REG8=write trigger).
 *
 * Source: Armino psram_hal.c -> psram_hal_cmd_write()
 ****************************************************************************/

static void psram_cmd_write(uint32_t addr, uint32_t value)
{
  psram_putreg(addr, PSRAM_LL_REG9);
  psram_putreg(value, PSRAM_LL_REGA);
  psram_putreg(PSRAM_CMD_WRITE_TRIG, PSRAM_LL_REG8);

  /* Wait for write to complete (bit auto-clears) */

  while (psram_getreg(PSRAM_LL_REG8) & PSRAM_CMD_WRITE_TRIG)
    {
    }
}

/****************************************************************************
 * Name: psram_cmd_read
 *
 * Description:
 *   Read a value from a PSRAM register address via the command
 *   interface.  Returns 0 on timeout/failure.
 *
 * Source: Armino psram_hal.c -> psram_hal_cmd_read()
 ****************************************************************************/

static uint32_t psram_cmd_read(uint32_t addr)
{
  int retry;
  int outer;
  int inner;

  for (retry = 0; retry < CMD_READ_RETRIES; retry++)
    {
      psram_putreg(addr, PSRAM_LL_REG9);
      psram_putreg(PSRAM_CMD_READ_TRIG, PSRAM_LL_REG8);

      for (outer = 0; outer < CMD_READ_POLL_OUTER; outer++)
        {
          for (inner = 0; inner < CMD_READ_POLL_INNER; inner++)
            {
              if (!(psram_getreg(PSRAM_LL_REG8) &
                    PSRAM_CMD_READ_TRIG))
                {
                  return psram_getreg(PSRAM_LL_REGB);
                }
            }
        }

      /* Timeout: reset SF interface and retry */

      psram_putreg(0, PSRAM_LL_REG2);
      psram_putreg(PSRAM_SF_RESET_BIT, PSRAM_LL_REG2);
      psram_cmd_reset();
    }

  return 0;
}

/****************************************************************************
 * Name: psram_try_detect
 *
 * Description:
 *   Try to detect a specific PSRAM type by writing its mode register,
 *   issuing a reset, and reading the chip ID.
 *
 * Input Parameters:
 *   mode_val  - Value for REG4 (PSRAM mode)
 *   drv_val   - Value for REG5 (drive strength)
 *   id_addr   - Address to read chip ID from
 *   expected  - Expected chip ID
 *
 * Returned Value:
 *   true if chip ID matches expected.
 *
 ****************************************************************************/

static bool psram_try_detect(uint32_t mode_val, uint32_t drv_val,
                             uint32_t id_addr, uint32_t expected)
{
  uint32_t id;

  psram_putreg(mode_val, PSRAM_LL_REG4);
  psram_putreg(drv_val, PSRAM_LL_REG5);
  psram_cmd_reset();
  psram_busy_delay(PSRAM_DELAY_SHORT);

  id = psram_cmd_read(id_addr);
  return (id == expected);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_psram_init
 *
 * Description:
 *   Initialize the BK7258 PSRAM controller and detect the external
 *   PSRAM chip.  Sets g_psram_chip_id and g_psram_size.
 *
 *   Sequence: voltage -> power/clk -> config -> detect -> default clk
 *
 *   NOTE: Cache coherency not addressed (no D-cache configured).
 *
 * Returned Value:
 *   OK on success (chip detected), -ENODEV if no known chip found.
 *
 ****************************************************************************/

int bk7258_psram_init(void)
{
  g_psram_chip_id = 0;
  g_psram_size = 0;

  /* Step 1: Set PSRAM LDO voltage to 1.95V and enable */

  psram_set_voltage();

  /* Step 2: Set init clock to 80 MHz */

  psram_enable_clock();

  /* Step 3: Release SF interface from reset */

  psram_release_sf_reset();
  psram_busy_delay(PSRAM_DELAY_LONG);

  /* Step 4: Auto-detect PSRAM chip type */

  if (psram_try_detect(PSRAM_MODE_APS6408L, PSRAM_DRV_APS6408L,
                       0, PSRAM_ID_APS6408L))
    {
      g_psram_chip_id = PSRAM_ID_APS6408L;
      g_psram_size = 8 * 1024 * 1024;
    }
  else if (psram_try_detect(PSRAM_MODE_APS128XXO,
                            PSRAM_DRV_APS128XXO,
                            0, PSRAM_ID_APS128XXO))
    {
      g_psram_chip_id = PSRAM_ID_APS128XXO;
      g_psram_size = 16 * 1024 * 1024;
    }
  else if (psram_try_detect(PSRAM_MODE_W955D8MKY,
                            PSRAM_DRV_W955D8MKY,
                            0x01000000,
                            PSRAM_ID_W955D8MKY))
    {
      g_psram_chip_id = PSRAM_ID_W955D8MKY;
      g_psram_size = 4 * 1024 * 1024;
    }
  else
    {
      printf("psram: no known chip detected\n");
      return -ENODEV;
    }

  /* Step 5: Switch to 120 MHz default clock */

  up_mdelay(1);
  psram_set_default_clock();

  printf("psram: init OK, chip ID=0x%04x, size=%lu KB\n",
         g_psram_chip_id,
         (unsigned long)(g_psram_size / 1024));
  return OK;
}

/****************************************************************************
 * Name: bk7258_psram_get_id
 *
 * Description:
 *   Return the detected PSRAM chip ID (0 if not initialized).
 *
 ****************************************************************************/

uint32_t bk7258_psram_get_id(void)
{
  return g_psram_chip_id;
}

/****************************************************************************
 * Name: bk7258_psram_get_size
 *
 * Description:
 *   Return the detected PSRAM size in bytes (0 if not initialized).
 *
 ****************************************************************************/

uint32_t bk7258_psram_get_size(void)
{
  return g_psram_size;
}

/****************************************************************************
 * Name: bk7258_psram_probe
 *
 * Description:
 *   Full S1 verification: init + ID check + single-word data path
 *   test on the memory-mapped window (0x60000000).
 *
 *   The ID check uses the command-register path (REG9/REG_A/REG_B).
 *   The data path test uses the AXI memory-mapped window.  These are
 *   two independent hardware paths; testing both in S1 ensures we
 *   don't mix up "controller works" with "data window works".
 *
 *   NOTE: Cache coherency not addressed (no D-cache configured).
 *
 * Returned Value:
 *   OK on success, negative errno on failure.
 *
 ****************************************************************************/

int bk7258_psram_probe(void)
{
  volatile uint32_t *psram_base;
  uint32_t save;
  uint32_t readback;
  int ret;

  /* Run full init sequence */

  ret = bk7258_psram_init();
  if (ret < 0)
    {
      return ret;
    }

  /* Single-word data path test on memory-mapped window */

  psram_base = (volatile uint32_t *)0x60000000;

  /* Save original content (avoid destructive test on first word) */

  save = *psram_base;

  /* Write test pattern */

  *psram_base = 0xdeadbeef;
  readback = *psram_base;

  /* Restore original content */

  *psram_base = save;

  if (readback != 0xdeadbeef)
    {
      printf("psram: data path FAIL (wrote 0xdeadbeef, "
             "read 0x%08lx)\n",
             (unsigned long)readback);
      return -EIO;
    }

  printf("psram: data path OK (0x60000000 verified)\n");
  return OK;
}

/****************************************************************************
 * NSH builtin: psram
 ****************************************************************************/

#ifdef CONFIG_NSH_BUILTIN_APPS

int psram_main(int argc, char *argv[])
{
  if (argc < 2)
    {
      printf("usage: psram <id|probe>\n");
      printf("  id     - read chip ID via cmd registers\n");
      printf("  probe  - init + ID + single-word data test\n");
      return -EINVAL;
    }

  if (strcmp(argv[1], "id") == 0)
    {
      int ret = bk7258_psram_init();
      if (ret < 0)
        {
          return ret;
        }

      printf("psram: chip ID = 0x%04x\n", g_psram_chip_id);
      printf("psram: size    = %lu KB (%lu MB)\n",
             (unsigned long)(g_psram_size / 1024),
             (unsigned long)(g_psram_size / (1024 * 1024)));
    }
  else if (strcmp(argv[1], "probe") == 0)
    {
      return bk7258_psram_probe();
    }
  else
    {
      printf("psram: unknown command '%s'\n", argv[1]);
      return -EINVAL;
    }

  return OK;
}

#endif /* CONFIG_NSH_BUILTIN_APPS */

