54	/* Busy-wait calibration: ~1 iteration per CPU cycle at 320 MHz.
55	 * Values taken from Armino; not critical (only used for power
56	 * settling delays).
57	 */
58	
59	#define PSRAM_DELAY_SHORT      500
60	#define PSRAM_DELAY_LONG       3000
61	#define CMD_READ_RETRIES       5
62	#define CMD_READ_POLL_OUTER    10
63	#define CMD_READ_POLL_INNER    5000
