76	/****************************************************************************
77	 * Name: psram_busy_delay
78	 *
79	 * Description:
80	 *   Simple busy-wait loop.  Duration is approximate and non-critical;
81	 *   used only for power/settling delays during initialization.
82	 *
83	 ****************************************************************************/
84	
85	static void psram_busy_delay(uint32_t count)
86	{
87	  volatile uint32_t i;
88	
89	  for (i = 0; i < count; i++)
90	    {
91	    }
92	}
