100	 ****************************************************************************/
101	
102	static inline void psram_putreg(uint32_t val, uint32_t addr)
103	{
104	  *(volatile uint32_t *)addr = val;
105	}
106	
107	static inline uint32_t psram_getreg(uint32_t addr)
108	{
109	  return *(volatile uint32_t *)addr;
110	}
