112	/****************************************************************************
113	 * Name: psram_set_voltage
114	 *
115	 * Description:
116	 *   Configure PSRAM LDO voltage to 1.95V (psldo_swb=1, vpsramsel=3)
117	 *   and enable the LDO.  Wait 1 ms for stabilization.
118	 *
119	 * Source: Armino sys_psram_driver.c -> sys_drv_psram_psldo_vsel()
120	 *         + sys_drv_psram_ldo_enable()
121	 ****************************************************************************/
122	
123	static void psram_set_voltage(void)
124	{
125	  psram_putreg(PSRAM_VOLTAGE_LDO_EN, SYS_ANA_REG13);
126	  up_mdelay(1);
127	}
