129	/****************************************************************************
130	 * Name: psram_enable_clock
131	 *
132	 * Description:
133	 *   Set PSRAM clock to 80 MHz for init phase (source=320 MHz PLL,
134	 *   divider=1).  The higher default clock is set after init completes.
135	 *
136	 * Source: Armino psram_hal.c -> psram_hal_set_clk(PSRAM_80M)
137	 ****************************************************************************/
138	
139	static void psram_enable_clock(void)
140	{
141	  uint32_t val;
142	
143	  /* Select 320 MHz PLL as source, divider = 1 -> 80 MHz */
144	
145	  val = psram_getreg(SYS_CPU_CLK_DIV2);
146	  val &= ~(CLK_DIV2_CKSEL_PSRAM | CLK_DIV2_CKDIV_PSRAM);
147	  val |= CLK_DIV2_CKDIV_PSRAM;
148	  psram_putreg(val, SYS_CPU_CLK_DIV2);
149	}
