158	 * Source: Armino psram_hal.c -> psram_hal_set_default_clk()
159	 ****************************************************************************/
160	
161	static void psram_set_default_clock(void)
162	{
163	  uint32_t val;
164	
165	  val = psram_getreg(SYS_CPU_CLK_DIV2);
166	  val &= ~(CLK_DIV2_CKSEL_PSRAM | CLK_DIV2_CKDIV_PSRAM);
167	  val |= (CLK_DIV2_CKSEL_PSRAM | CLK_DIV2_CKDIV_PSRAM);
168	  psram_putreg(val, SYS_CPU_CLK_DIV2);
169	}
