199	/****************************************************************************
200	 * Name: psram_cmd_write
201	 *
202	 * Description:
203	 *   Write a value to a PSRAM register address via the command
204	 *   interface (REG9=addr, REG_A=value, REG8=write trigger).
205	 *
206	 * Source: Armino psram_hal.c -> psram_hal_cmd_write()
207	 ****************************************************************************/
208	
209	static void psram_cmd_write(uint32_t addr, uint32_t value)
210	{
211	  psram_putreg(addr, PSRAM_LL_REG9);
212	  psram_putreg(value, PSRAM_LL_REGA);
213	  psram_putreg(PSRAM_CMD_WRITE_TRIG, PSRAM_LL_REG8);
214	
215	  /* Wait for write to complete (bit auto-clears) */
216	
217	  while (psram_getreg(PSRAM_LL_REG8) & PSRAM_CMD_WRITE_TRIG)
218	    {
219	    }
220	}
221	
222	/****************************************************************************
223	 * Name: psram_cmd_read
224	 *
225	 * Description:
226	 *   Read a value from a PSRAM register address via the command
227	 *   interface.  Returns 0 on timeout/failure.
228	 *
229	 * Source: Armino psram_hal.c -> psram_hal_cmd_read()
230	 ****************************************************************************/
231	
232	static uint32_t psram_cmd_read(uint32_t addr)
233	{
234	  int retry;
235	  int outer;
236	  int inner;
237	
238	  for (retry = 0; retry < CMD_READ_RETRIES; retry++)
239	    {
240	      psram_putreg(addr, PSRAM_LL_REG9);
241	      psram_putreg(PSRAM_CMD_READ_TRIG, PSRAM_LL_REG8);
242	
243	      for (outer = 0; outer < CMD_READ_POLL_OUTER; outer++)
244	        {
245	          for (inner = 0; inner < CMD_READ_POLL_INNER; inner++)
246	            {
247	              if (!(psram_getreg(PSRAM_LL_REG8) &
248	                    PSRAM_CMD_READ_TRIG))
249	                {
250	                  return psram_getreg(PSRAM_LL_REGB);
251	                }
252	            }
253	        }
254	
255	      /* Timeout: reset SF interface and retry */
256	
257	      psram_putreg(0, PSRAM_LL_REG2);
258	      psram_putreg(PSRAM_SF_RESET_BIT, PSRAM_LL_REG2);
259	      psram_cmd_reset();
260	    }
261	
262	  return 0;
263	}
