265	/****************************************************************************
266	 * Name: psram_try_detect
267	 *
268	 * Description:
269	 *   Try to detect a specific PSRAM type by writing its mode register,
270	 *   issuing a reset, and reading the chip ID.
271	 *
272	 * Input Parameters:
273	 *   mode_val  - Value for REG4 (PSRAM mode)
274	 *   drv_val   - Value for REG5 (drive strength)
275	 *   id_addr   - Address to read chip ID from
276	 *   expected  - Expected chip ID
277	 *
278	 * Returned Value:
279	 *   true if chip ID matches expected.
280	 *
281	 ****************************************************************************/
282	
283	static bool psram_try_detect(uint32_t mode_val, uint32_t drv_val,
284	                             uint32_t id_addr, uint32_t expected)
285	{
286	  uint32_t id;
287	
288	  psram_putreg(mode_val, PSRAM_LL_REG4);
289	  psram_putreg(drv_val, PSRAM_LL_REG5);
290	  psram_cmd_reset();
291	  psram_busy_delay(PSRAM_DELAY_SHORT);
292	
293	  id = psram_cmd_read(id_addr);
294	  return (id == expected);
295	}
