298	 * Public Functions
299	 ****************************************************************************/
300	
301	/****************************************************************************
302	 * Name: bk7258_psram_init
303	 *
304	 * Description:
305	 *   Initialize the BK7258 PSRAM controller and detect the external
306	 *   PSRAM chip.  Sets g_psram_chip_id and g_psram_size.
307	 *
308	 *   Sequence: voltage -> power/clk -> config -> detect -> default clk
309	 *
310	 *   NOTE: Cache coherency not addressed (no D-cache configured).
311	 *
312	 * Returned Value:
313	 *   OK on success (chip detected), -ENODEV if no known chip found.
314	 *
315	 ****************************************************************************/
316	
317	int bk7258_psram_init(void)
318	{
319	  g_psram_chip_id = 0;
320	  g_psram_size = 0;
321	
322	  /* Step 1: Set PSRAM LDO voltage to 1.95V and enable */
323	
324	  psram_set_voltage();
325	
326	  /* Step 2: Set init clock to 80 MHz */
327	
328	  psram_enable_clock();
329	
330	  /* Step 3: Release SF interface from reset */
331	
332	  psram_release_sf_reset();
333	  psram_busy_delay(PSRAM_DELAY_LONG);
334	
335	  /* Step 4: Auto-detect PSRAM chip type */
336	
337	  if (psram_try_detect(PSRAM_MODE_APS6408L, PSRAM_DRV_APS6408L,
338	                       0, PSRAM_ID_APS6408L))
339	    {
340	      g_psram_chip_id = PSRAM_ID_APS6408L;
341	      g_psram_size = 8 * 1024 * 1024;
342	    }
343	  else if (psram_try_detect(PSRAM_MODE_APS128XXO,
344	                            PSRAM_DRV_APS128XXO,
345	                            0, PSRAM_ID_APS128XXO))
346	    {
347	      g_psram_chip_id = PSRAM_ID_APS128XXO;
348	      g_psram_size = 16 * 1024 * 1024;
349	    }
350	  else if (psram_try_detect(PSRAM_MODE_W955D8MKY,
351	                            PSRAM_DRV_W955D8MKY,
352	                            0x01000000,
353	                            PSRAM_ID_W955D8MKY))
354	    {
355	      g_psram_chip_id = PSRAM_ID_W955D8MKY;
356	      g_psram_size = 4 * 1024 * 1024;
357	    }
358	  else
359	    {
360	      printf("psram: no known chip detected\n");
361	      return -ENODEV;
362	    }
363	
364	  /* Step 5: Switch to 120 MHz default clock */
365	
366	  up_mdelay(1);
367	  psram_set_default_clock();
368	
369	  printf("psram: init OK, chip ID=0x%04x, size=%lu KB\n",
370	         g_psram_chip_id,
371	         (unsigned long)(g_psram_size / 1024));
372	  return OK;
373	}
374	
375	/****************************************************************************
376	 * Name: bk7258_psram_get_id
377	 *
378	 * Description:
379	 *   Return the detected PSRAM chip ID (0 if not initialized).
380	 *
381	 ****************************************************************************/
382	
383	uint32_t bk7258_psram_get_id(void)
384	{
385	  return g_psram_chip_id;
386	}
387	
388	/****************************************************************************
389	 * Name: bk7258_psram_get_size
390	 *
391	 * Description:
392	 *   Return the detected PSRAM size in bytes (0 if not initialized).
393	 *
394	 ****************************************************************************/
395	
396	uint32_t bk7258_psram_get_size(void)
397	{
398	  return g_psram_size;
399	}
400	
401	/****************************************************************************
402	 * Name: bk7258_psram_probe
403	 *
404	 * Description:
405	 *   Full S1 verification: init + ID check + single-word data path
406	 *   test on the memory-mapped window (0x60000000).
407	 *
408	 *   The ID check uses the command-register path (REG9/REG_A/REG_B).
409	 *   The data path test uses the AXI memory-mapped window.  These are
410	 *   two independent hardware paths; testing both in S1 ensures we
411	 *   don't mix up "controller works" with "data window works".
412	 *
413	 *   NOTE: Cache coherency not addressed (no D-cache configured).
414	 *
415	 * Returned Value:
416	 *   OK on success, negative errno on failure.
417	 *
418	 ****************************************************************************/
419	
420	int bk7258_psram_probe(void)
421	{
422	  volatile uint32_t *psram_base;
423	  uint32_t save;
424	  uint32_t readback;
425	  int ret;
426	
427	  /* Run full init sequence */
428	
429	  ret = bk7258_psram_init();
430	  if (ret < 0)
431	    {
432	      return ret;
433	    }
434	
435	  /* Single-word data path test on memory-mapped window */
436	
437	  psram_base = (volatile uint32_t *)0x60000000;
438	
439	  /* Save original content (avoid destructive test on first word) */
440	
441	  save = *psram_base;
442	
443	  /* Write test pattern */
444	
445	  *psram_base = 0xdeadbeef;
446	  readback = *psram_base;
447	
448	  /* Restore original content */
449	
450	  *psram_base = save;
451	
452	  if (readback != 0xdeadbeef)
453	    {
454	      printf("psram: data path FAIL (wrote 0xdeadbeef, "
455	             "read 0x%08lx)\n",
456	             (unsigned long)readback);
457	      return -EIO;
458	    }
459	
460	  printf("psram: data path OK (0x60000000 verified)\n");
461	  return OK;
462	}
463	
464	/* NSH command handler: called from apps/examples/psram/ */
465	
466	int bk7258_psram_main(int argc, char *argv[])
467	{
468	  if (argc < 2)
469	    {
470	      printf("usage: psram <id|probe>\n");
471	      printf("  id     - read chip ID via cmd registers\n");
472	      printf("  probe  - init + ID + single-word data test\n");
473	      return -EINVAL;
474	    }
475	
476	  if (strcmp(argv[1], "id") == 0)
477	    {
478	      int ret = bk7258_psram_init();
479	      if (ret < 0)
480	        {
481	          return ret;
482	        }
483	
484	      printf("psram: chip ID = 0x%04x\n", g_psram_chip_id);
485	      printf("psram: size    = %lu KB (%lu MB)\n",
486	             (unsigned long)(g_psram_size / 1024),
487	             (unsigned long)(g_psram_size / (1024 * 1024)));
488	    }
489	  else if (strcmp(argv[1], "probe") == 0)
490	    {
491	      return bk7258_psram_probe();
492	    }
493	  else
494	    {
495	      printf("psram: unknown command '%s'\n", argv[1]);
496	      return -EINVAL;
497	    }
498	
499	  return OK;
500	}
